  requires 0 <= i <= a.Length
  ensures b.Length == a.Length
  ensures forall k :: 0 <= k < i ==> b[k] == sum(a, k)
  ensures forall k :: i <= k < a.Length ==> b[k] == a[k]
{
  b := new int[a.Length];

  // Initialize all elements of b with a's values
  var idx: int := 0;
  while idx < a.Length
    invariant 0 <= idx <= a.Length
    invariant forall k :: 0 <= k < idx ==> b[k] == a[k]
  {
    b[idx] := a[idx];
    idx := idx + 1;
  }

  // If i == 0, we're done (no cumulative sum needed)
  if i == 0 {
